#!/usr/bin/env bash
# Enforcer-MCP one-shot installer.
# Paste this entire file into the cockpit's KALI Terminal (Classic sub-tab)
# OR scp/wget it into the chroot and: bash enforcer-mcp-installer.sh
#
# Idempotent: re-running upgrades in place. Existing config.yaml is preserved.

set -euo pipefail

INSTALL_DIR="/opt/enforcer-mcp"
CONFIG_DIR="/etc/enforcer-mcp"
CONFIG_FILE="$CONFIG_DIR/config.yaml"

echo "[enforcer-mcp] ensuring install dirs"
mkdir -p "$INSTALL_DIR" "$CONFIG_DIR"

echo "[enforcer-mcp] extracting payload"
TMPDIR="$(mktemp -d)"
trap 'rm -rf "$TMPDIR"' EXIT
base64 -d > "$TMPDIR/payload.tgz" <<'PAYLOAD_B64'

PAYLOAD_B64
tar xzf "$TMPDIR/payload.tgz" -C "$TMPDIR"
cp -r "$TMPDIR/enforcer-mcp/." "$INSTALL_DIR/"

echo "[enforcer-mcp] python3 venv + deps"
cd "$INSTALL_DIR"
if [ ! -d .venv ]; then
  python3 -m venv .venv
fi
. .venv/bin/activate
pip install --quiet --upgrade pip
pip install --quiet -r requirements.txt

echo "[enforcer-mcp] writing config (preserves existing)"
if [ ! -f "$CONFIG_FILE" ]; then
  cp "$INSTALL_DIR/config.yaml.example" "$CONFIG_FILE"
  echo "  -> first install: edit $CONFIG_FILE and paste the bearer token from"
  echo "     the cockpit's MCP tab (// status → REVEAL → COPY)"
else
  echo "  -> config exists, leaving untouched"
fi

cat <<DONE

============================================================
 enforcer-mcp installed in $INSTALL_DIR
 config:                 $CONFIG_FILE
 audit db (auto-creates next to config on first run)

 Edit the bearer token, then run:

   cd $INSTALL_DIR
   source .venv/bin/activate
   python3 server.py --config $CONFIG_FILE

 Smoke test (in another shell):
   curl -s http://127.0.0.1:8765/health | head
============================================================
DONE
